import Foundation
import SwiftUI
import RxSwift
import Combine

/// Login Presenter
/// Handles the presentation logic and coordinates between View, Interactor, and Wireframe
final class LoginPresenter: ObservableObject {

    // MARK: - Published Properties (UI State)
    
    @Published var email: String = ""
    @Published var password: String = ""
    @Published var isRememberMeEnabled: Bool = false
    @Published var areActionsEnabled: Bool = false
    @Published var isLoading: Bool = false
    @Published var isSecureTextEntry: Bool = true
    @Published var errorMessage: String? = nil

    // MARK: - Private Properties
    
    private let interactor: LoginInteractorInterface
    private let wireframe: LoginWireframeInterface
    
    private let emailValidator: EmailValidator
    private let passwordValidator: PasswordValidator
    private let disposeBag = DisposeBag()
    private var cancellables = Set<AnyCancellable>()

    // MARK: - Initialization
    
    /// Initialize the presenter with its dependencies
    /// - Parameters:
    ///   - interactor: The interactor handling business logic
    ///   - wireframe: The wireframe handling navigation
    init(
        interactor: LoginInteractorInterface,
        wireframe: LoginWireframeInterface
    ) {
        self.interactor = interactor
        self.wireframe = wireframe
        
        self.emailValidator = EmailValidator()
        self.passwordValidator = PasswordValidator(minLength: 6)
        
        setupValidationBinding()
    }
}

// MARK: - Public Methods

extension LoginPresenter {
    
    /// Attempt to log in with current email and password
    func login() {
        guard areActionsEnabled else { return }
        
        isLoading = true
        errorMessage = nil
        
        interactor
            .login(with: email, password)
            .observe(on: MainScheduler.instance)
            .subscribe(
                onSuccess: { [weak self] user in
                    self?.handleSuccessfulAuth(user: user)
                },
                onFailure: { [weak self] error in
                    self?.isLoading = false
                    self?.errorMessage = error.localizedDescription
                }
            )
            .disposed(by: disposeBag)
    }
    
    /// Attempt to register with current email and password  
    func register() {
        guard areActionsEnabled else { return }
        
        isLoading = true
        errorMessage = nil
        
        interactor
            .register(with: email, password)
            .observe(on: MainScheduler.instance)
            .subscribe(
                onSuccess: { [weak self] user in
                    self?.handleSuccessfulAuth(user: user)
                },
                onFailure: { [weak self] error in
                    self?.isLoading = false
                    self?.errorMessage = error.localizedDescription
                }
            )
            .disposed(by: disposeBag)
    }
    
    /// Toggle remember me state
    func toggleRememberMe() {
        isRememberMeEnabled.toggle()
    }
    
    /// Toggle secure text entry for password field
    func toggleSecureTextEntry() {
        isSecureTextEntry.toggle()
    }
    
    /// Clear any existing error message
    func clearError() {
        errorMessage = nil
    }
}

// MARK: - Private Methods

private extension LoginPresenter {
    
    func setupValidationBinding() {
        // Use Combine publishers from @Published properties to observe changes
        Publishers.CombineLatest($email, $password)
            .map { [weak self] email, password in
                guard let self = self else { return false }
                return self.isEmailValid(email) && self.isPasswordValid(password)
            }
            .assign(to: \.areActionsEnabled, on: self)
            .store(in: &cancellables)
    }
    
    func handleSuccessfulAuth(user: User) {
        isLoading = false
        
        if isRememberMeEnabled {
            interactor.rememberUser()
        }
        
        wireframe.navigateToHome()
    }
    
    func isEmailValid(_ email: String) -> Bool {
        return emailValidator.isValid(email)
    }
    
    func isPasswordValid(_ password: String) -> Bool {
        return passwordValidator.isValid(password)
    }
}
